// Input HIGH: pin 9 holds the TIP120 fully on
const int IN = 9;          // to R1 (1 kΩ), then the TIP120's base

void setup() {
  pinMode(IN, OUTPUT);
  Serial.begin(9600);
  digitalWrite(IN, HIGH);  // about 3.4 mA into the base...
  Serial.println("pin 9 HIGH: TIP120 on, motor runs");
}

void loop() {}             // ...lets the battery's 160 mA flow through the motor
// a pin gives 20 mA at most: never wire a motor to it

// Input LOW: pin 9 holds the TIP120 off
const int IN = 9;

void setup() {
  pinMode(IN, OUTPUT);
  Serial.begin(9600);
  digitalWrite(IN, LOW);   // no base current: the TIP120 is off
  Serial.println("pin 9 LOW: TIP120 off, motor coasts to a stop");
}

void loop() {}             // the coil's energy dumps through D1 and the motor coasts to a stop

// PWM 50%: pin 9 switches the TIP120 on and off 490 times a second
const int IN = 9;          // a ~ pin: hardware PWM from Timer1

void setup() {
  pinMode(IN, OUTPUT);
  Serial.begin(9600);
  analogWrite(IN, 128);    // 128 of 255 = 50% duty at 490 Hz
  Serial.println("analogWrite(9, 128): 490 Hz, 50% duty");
}

void loop() {}             // the motor averages it out: a bit under half speed, and a whine
// in every off-time D1 carries the coil's current round the motor

// Soft start: raise the duty one step every 8 ms, no delay()
const int IN = 9;
int duty = 0;
unsigned long lastStep = 0;
unsigned long lastPrint = 0;

void setup() {
  pinMode(IN, OUTPUT);
  Serial.begin(9600);
  Serial.println("soft start: 0 to 255 in about 2 s");
}

void loop() {
  unsigned long now = millis();
  if (duty < 255 && now - lastStep >= 8) {   // 255 steps of 8 ms is about 2 s from stop to full speed
    lastStep = now;
    duty++;
    analogWrite(IN, duty);
  }
  if (now - lastPrint >= 1000) {             // report the duty once a second
    lastPrint = now;
    Serial.print("duty ");
    Serial.println(duty);
  }
}
